package com.acme.lambda;

import com.amazonaws.services.lambda.runtime.Context;
import com.amazonaws.services.lambda.runtime.RequestHandler;
import com.amazonaws.services.lambda.runtime.events.APIGatewayProxyRequestEvent;
import com.amazonaws.services.lambda.runtime.events.APIGatewayProxyResponseEvent;
import io.quarkus.amazon.lambda.http.model.AwsProxyRequest;
import software.amazon.awssdk.services.s3.S3Client;
import software.amazon.awssdk.services.s3.model.PutObjectRequest;

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Map;
import java.util.stream.Collectors;

public class DiagnosticHandler implements RequestHandler<APIGatewayProxyRequestEvent, APIGatewayProxyResponseEvent> {

    private final S3Client s3Client = S3Client.create();
    private static final String DIAGNOSTIC_BUCKET = System.getenv("DIAGNOSTIC_BUCKET");
    private static final String ALLOWED_TOOLS = "ping,traceroute,dig,nslookup";

    @Override
    public APIGatewayProxyResponseEvent handleRequest(APIGatewayProxyRequestEvent input, Context context) {
        APIGatewayProxyResponseEvent response = new APIGatewayProxyResponseEvent();
        response.setHeaders(Map.of("Content-Type", "application/json"));

        try {
            Map<String, String> queryParams = input.getQueryStringParameters();
            if (queryParams == null || !queryParams.containsKey("tool") || !queryParams.containsKey("target")) {
                response.setStatusCode(400);
                response.setBody("{\"error\": \"Missing required parameters: tool, target\"}");
                return response;
            }

            String tool = queryParams.get("tool");
            String target = queryParams.get("target");

            // Validate tool is in allowed list
            if (!ALLOWED_TOOLS.contains(tool.toLowerCase())) {
                response.setStatusCode(403);
                response.setBody("{\"error\": \"Tool not permitted\"}");
                return response;
            }

            // Validate target looks like a hostname or IP
            if (!target.matches("[a-zA-Z0-9._-]+")) {
                response.setStatusCode(400);
                response.setBody("{\"error\": \"Invalid target format\"}");
                return response;
            }

            // Execute diagnostic command
            String command = String.format("/usr/bin/%s -c 3 %s", tool, target);
            context.getLogger().log("Executing: " + command);

            ProcessBuilder pb = new ProcessBuilder("/bin/sh", "-c", command);
            pb.redirectErrorStream(true);
            Process process = pb.start();

            String output;
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
                output = reader.lines().collect(Collectors.joining("\n"));
            }
            int exitCode = process.waitFor();

            // Upload result to S3 for audit trail
            String key = String.format("diagnostics/%s/%s-%d.txt",
                    context.getAwsRequestId(), tool, System.currentTimeMillis());
            Path tempFile = Files.createTempFile("diag-", ".txt");
            Files.writeString(tempFile, output);

            s3Client.putObject(
                    PutObjectRequest.builder()
                            .bucket(DIAGNOSTIC_BUCKET)
                            .key(key)
                            .build(),
                    tempFile
            );
            Files.delete(tempFile);

            response.setStatusCode(200);
            response.setBody(String.format(
                    "{\"tool\": \"%s\", \"target\": \"%s\", \"exitCode\": %d, \"output\": \"%s\", \"s3Key\": \"%s\"}",
                    tool, target, exitCode, output.replace("\"", "\\\"").replace("\n", "\\n"), key));

        } catch (Exception e) {
            context.getLogger().log("Error: " + e.getMessage());
            response.setStatusCode(500);
            response.setBody("{\"error\": \"Internal diagnostic failure\"}");
        }

        return response;
    }
}
